SET @prov_c := '%s';
SET @id := '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET @start_d1:=concat(@b_year-2,'1001');
SET @end_d1:=concat(@b_year-1,'0930');
SET @start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');


CREATE TABLE IF NOT EXISTS s_kpi_sp5_orthopedic (
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	splevel varchar(2) DEFAULT NULL,
	A int(9) DEFAULT 0,
	B int(9) DEFAULT 0,
	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_kpi_sp5_orthopedic WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_kpi_sp5_orthopedic 
(
SELECT
  @id,HOSPCODE,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
  ,splevel,COUNT(DISTINCT IF(date_serv BETWEEN @start_d1 AND @end_d1 ,CONCAT(hospcode,'-',pid,'-',date_serv),NULL)) A
 ,COUNT(DISTINCT IF(date_serv BETWEEN @start_d AND @end_d ,CONCAT(hospcode,'-',pid,'-',date_serv),NULL)) B
FROM
t_refer_sp5  s LEFT JOIN chospital h ON s.hospcode=h.hoscode
WHERE
h.provcode in(@prov_c) AND splevel in('A','S') AND referin_splevel in('M2') AND clinic in(5)
GROUP BY hospcode
);
